{
    public string Name { get; }
    protected Enemy(string name) { Name = name; }
    public abstract string Act(int distance);
}

public class Goblin : Enemy
{
    public Goblin(string name) : base(name) { }
    public override string Act(int distance) => distance <= 1 ? $"{Name} attacks" : $"{Name} runs closer";
}

public class Archer : Enemy
{
    public Archer(string name) : base(name) { }
    public override string Act(int distance) => distance >= 3 ? $"{Name} shoots" : $"{Name} steps back";
}

class Program
{
    static string Weigh(object thing) => thing switch
    {
        int n when n > 100 => "heavy number",
        int n => $"number {n}",
        string s => $"text of {s.Length} letters",
        null => "nothing",
        _ => "something else"
    };

    static void Main()
    {
        var wave = new List<Enemy> { new Goblin("Snik"), new Archer("Kip") };
        foreach (Enemy e in wave) Console.WriteLine(e.Act(4));
        Console.WriteLine(Weigh(500) + ", " + Weigh("maize") + ", " + Weigh(null));
    }
}

