using System;
using System.Collections.Generic;
using System.Linq;

public abstract class Enemy
{
    public string Name { get; }

    protected Enemy(string name)
    {
        Name = name;
    }

    public abstract string Act(int distance);
}

public class Goblin : Enemy
{
    public Goblin(string name) : base(name) { }

    public override string Act(int distance) => distance <= 1 ? $"{Name} attacks" : $"{Name} runs closer";
}

public class Archer : Enemy
{
    public Archer(string name) : base(name) { }

    public override string Act(int distance) => distance >= 3 ? $"{Name} shoots" : $"{Name} steps back";
}

public class Healer : Enemy
{
    public Healer(string name) : base(name) { }

    public override string Act(int distance) => $"{Name} heals the wave";
}

public static class Wave
{
    // No type checks here: each enemy knows what it does.
    public static List<string> TakeTurn(List<Enemy> enemies, int distance) =>
        enemies.Select(e => e.Act(distance)).ToList();
}

