using System;
using System.Collections.Generic;
using System.Linq;

public class Coin
{
    public int Value { get; }
    public Coin(int value) { Value = value; }
}

public class Potion
{
    public int Heal { get; }
    public Potion(int heal) { Heal = heal; }
}

public class Key
{
    public string Door { get; }
    public Key(string door) { Door = door; }
}

public static class Pickup
{
    // First matching arm wins, so the special big coin comes before any coin.
    public static string Describe(object item) => item switch
    {
        null => "Nothing",
        Coin { Value: >= 100 } c => $"Treasure! {c.Value} gold",
        Coin c => $"{c.Value} gold",
        Potion p => $"Potion (+{p.Heal} HP)",
        Key k => $"Key to the {k.Door}",
        string note => $"Note: {note}",
        _ => "Unknown item"
    };
}

