using System;
using System.Collections.Generic;
using System.Linq;

public class Coin
{
    public int Value { get; }
    public Coin(int value) { Value = value; }
}

public class Potion
{
    public int Heal { get; }
    public Potion(int heal) { Heal = heal; }
}

public class Key
{
    public string Door { get; }
    public Key(string door) { Door = door; }
}

public static class Loot
{
    public static int TotalGold(List<object> items)
    {
        int total = 0;
        foreach (object item in items)
        {
            if (item is Coin c) total += c.Value;      // checks the type AND names it
            else if (item is Potion) total += 10;      // a type check without a name
        }
        return total;                                   // null is never "is" anything, so it's skipped
    }

    public static bool CanOpen(List<object> items, string door)
    {
        foreach (object item in items)
            if (item is Key k && string.Equals(k.Door, door, StringComparison.OrdinalIgnoreCase)) return true;
        return false;
    }
}
